record.field:
for review in records:
    wa = env["work.acceptance"].browse(review.res_id)
    if not wa.exists():
        continue
    for user in review.reviewer_ids:
        wa.activity_schedule(
            "purchase_work_acceptance_todo.mail_activity_wa_review_requested",
            summary="Work acceptance %s awaits your review" % (wa.name or ""),
            user_id=user.id,
        )

Activity = env["mail.activity"].sudo()
act_type = env.ref(
    "purchase_work_acceptance_todo.mail_activity_wa_review_requested",
    raise_if_not_found=False,
)
if act_type:
    for review in records:
        Activity.search([
            ("res_model", "=", "work.acceptance"),
            ("res_id", "=", review.res_id),
            ("activity_type_id", "=", act_type.id),
            ("user_id", "in", review.reviewer_ids.ids),
        ]).unlink()
